#!/usr/bin/env python3
"""Compute the rainfall-load uncertainty-propagation ground truth for CSX-058_Q1."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path


TASK_ID = "CSX-058_Q1"
EVENT_ID = "CSX-058"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_April_2024_UAE_and_Dubai_record_rainfall_flood.json",
    "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self.skip_depth and data.strip():
            self.parts.append(data.strip())


def package_root() -> Path:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    return repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def load_json(pkg: Path, rel_path: str) -> dict:
    return json.loads((pkg / rel_path).read_text(encoding="utf-8", errors="replace"))


def html_text(pkg: Path, rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((pkg / rel_path).read_text(encoding="utf-8", errors="replace"))
    return re.sub(r"\s+", " ", " ".join(parser.parts))


def first_number(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1))


def main() -> None:
    pkg = package_root()

    event = load_json(pkg, SOURCE_FILES[0])
    anchor = load_json(pkg, SOURCE_FILES[1])
    report = html_text(pkg, SOURCE_FILES[2])

    annual_match = re.search(r"only about ([0-9]+) to ([0-9]+) millimeters", report, flags=re.IGNORECASE)
    if not annual_match:
        raise ValueError("Annual rainfall range not found in report")

    peak_24h_mm = first_number(r"up to ([0-9]+) millimeters", report)
    annual_low_mm = float(annual_match.group(1))
    annual_high_mm = float(annual_match.group(2))
    airport_mm = first_number(r"recorded ([0-9]+) millimeters on April 16", report)
    airport_multiplier = first_number(r"which is ([0-9.]+) times its typical annual rainfall", report)

    peak_vs_annual_high = round(peak_24h_mm / annual_high_mm, 2)
    airport_implied_annual_mm = round(airport_mm / airport_multiplier, 2)
    airport_vs_implied_annual = round(airport_mm / airport_implied_annual_mm, 2)
    airport_vs_country_annual_high = round(airport_mm / annual_high_mm, 2)
    peak_margin = round(peak_vs_annual_high - 1.0, 2)
    airport_margin = round(airport_vs_implied_annual - 1.0, 2)

    classification_result = (
        "annual_load_compression_pass"
        if peak_vs_annual_high >= 1.0 and airport_vs_implied_annual >= 1.0
        else "annual_load_compression_fail"
    )

    primary_answer = {
        "answer": classification_result,
        "target_family": "dubai_rainfall_load_uncertainty_propagation",
        "rainfall_anchors": {
            "peak_24h_mm": peak_24h_mm,
            "annual_high_mm": annual_high_mm,
            "airport_mm": airport_mm,
            "airport_reported_multiplier": airport_multiplier,
        },
        "computed_ratios": {
            "peak_vs_annual_high": peak_vs_annual_high,
            "airport_implied_annual_mm": airport_implied_annual_mm,
            "airport_vs_implied_annual": airport_vs_implied_annual,
        },
        "uncertainty_margins": {
            "peak_vs_annual_high_margin_above_1": peak_margin,
            "airport_vs_implied_annual_margin_above_1": airport_margin,
            "most_sensitive_anchor": "peak_24h_mm_or_annual_high_mm",
            "robust_to_small_anchor_error": True,
        },
        "decision_rule": "pass if peak_vs_annual_high >= 1.0 and airport_vs_implied_annual >= 1.0",
        "classification_result": classification_result,
        "mechanism_label": "arid_urban_pluvial_runoff",
        "rejected_alternative": "coastal_surge_or_large_river_primary_driver",
