    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "hazard_label": event["hazard_label"],
            "country_or_region": anchor["spatial_window"]["country_or_region"],
            "location_text": anchor["spatial_window"]["location_text"],
            "event_start_date": anchor["temporal_window"]["start_date"],
            "event_end_date": anchor["temporal_window"]["end_date"],
