        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_answer,
        "key_values": {
            "rainfall_anchors": {
                "eastern_uae_less_than_24h_peak_mm": peak_24h_mm,
                "uae_typical_annual_rainfall_range_mm": [annual_low_mm, annual_high_mm],
                "dubai_airport_april16_rain_mm": airport_mm,
